// Morning Brief - deterministic, Arabic, today only.
// This module is pure so it can be tested locally and embedded in the n8n Code node.
const TZ = 'Africa/Cairo';

function txt(value) {
  return value === undefined || value === null ? '' : String(value);
}

function clip(value, max) {
  const s = txt(value).replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, Math.max(0, max - 1)).trimEnd() + '…' : s;
}

function pick(object, ...keys) {
  for (const key of keys) {
    const value = object && object[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return '';
}

function headerValue(message, name) {
  const headers = message && (message.headers || (message.payload && message.payload.headers));
  if (Array.isArray(headers)) {
    const hit = headers.find((item) => txt(item && item.name).toLowerCase() === name.toLowerCase());
    return hit ? hit.value : '';
  }
  if (headers && typeof headers === 'object') {
    const key = Object.keys(headers).find((item) => item.toLowerCase() === name.toLowerCase());
    return key ? headers[key] : '';
  }
  return '';
}

function dayKey(value) {
  if (!value) return '';
  const raw = txt(value).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return '';
  try {
    return new Intl.DateTimeFormat('en-CA', {
      timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
    }).format(date);
  } catch (error) {
    return '';
  }
}

function timeLabel(value) {
  if (!value) return '';
  const raw = txt(value).trim();
  if (/^\d{1,2}:\d{2}/.test(raw)) {
    const [hour, minute] = raw.split(':');
    const h = Number(hour);
    const suffix = h < 12 ? 'ص' : 'م';
    const display = ((h + 11) % 12) + 1;
    return display + ':' + String(Number(minute)).padStart(2, '0') + ' ' + suffix;
  }
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return raw;
  try {
    return new Intl.DateTimeFormat('ar-EG-u-nu-latn', {
      timeZone: TZ, hour: 'numeric', minute: '2-digit', hour12: true,
    }).format(date);
  } catch (error) {
    return raw;
  }
}

function dateLabel(value) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return '';
  try {
    return new Intl.DateTimeFormat('ar-EG-u-nu-latn', {
      timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
    }).format(date);
  } catch (error) {
    return '';
  }
}

function shortDate(value) {
  const key = dayKey(value);
  if (!key) return '';
  const [year, month, day] = key.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day, 12));
  try {
    return new Intl.DateTimeFormat('ar-EG-u-nu-latn', {
      timeZone: 'UTC', day: 'numeric', month: 'short',
    }).format(date);
  } catch (error) {
    return key;
  }
}

function temp(value) {
  const n = Number(value);
  return Number.isFinite(n) ? Math.round(n) + '°م' : '';
}

const WMO_AR = {
  0: 'سماء صافية',
  1: 'صافية غالباً',
  2: 'غائم جزئياً',
  3: 'غائم',
  45: 'ضباب',
  48: 'ضباب متجمد',
  51: 'رذاذ خفيف',
  53: 'رذاذ متوسط',
  55: 'رذاذ كثيف',
  56: 'رذاذ متجمد خفيف',
  57: 'رذاذ متجمد كثيف',
  61: 'مطر خفيف',
  63: 'مطر متوسط',
  65: 'مطر غزير',
  66: 'مطر متجمد خفيف',
  67: 'مطر متجمد غزير',
  71: 'ثلج خفيف',
  73: 'ثلج متوسط',
  75: 'ثلج غزير',
  77: 'حبيبات ثلج',
  80: 'زخات مطر خفيفة',
  81: 'زخات مطر متوسطة',
  82: 'زخات مطر عنيفة',
  85: 'زخات ثلج خفيفة',
  86: 'زخات ثلج غزيرة',
  95: 'عاصفة رعدية',
  96: 'عاصفة رعدية مع برد خفيف',
  99: 'عاصفة رعدية مع برد غزير',
};

const DESC_AR = {
  'clear sky': 'سماء صافية',
  'mainly clear': 'صافية غالباً',
  'partly cloudy': 'غائم جزئياً',
  'overcast': 'غائم',
  'fog': 'ضباب',
  'depositing rime fog': 'ضباب متجمد',
  'light drizzle': 'رذاذ خفيف',
  'moderate drizzle': 'رذاذ متوسط',
  'dense drizzle': 'رذاذ كثيف',
  'light freezing drizzle': 'رذاذ متجمد خفيف',
  'dense freezing drizzle': 'رذاذ متجمد كثيف',
  'slight rain': 'مطر خفيف',
  'moderate rain': 'مطر متوسط',
  'heavy rain': 'مطر غزير',
  'light freezing rain': 'مطر متجمد خفيف',
  'heavy freezing rain': 'مطر متجمد غزير',
  'slight snow': 'ثلج خفيف',
  'moderate snow': 'ثلج متوسط',
  'heavy snow': 'ثلج غزير',
  'snow grains': 'حبيبات ثلج',
  'slight rain showers': 'زخات مطر خفيفة',
  'moderate rain showers': 'زخات مطر متوسطة',
  'violent rain showers': 'زخات مطر عنيفة',
  'slight snow showers': 'زخات ثلج خفيفة',
  'heavy snow showers': 'زخات ثلج غزيرة',
  'thunderstorm': 'عاصفة رعدية',
  'thunderstorm with slight hail': 'عاصفة رعدية مع برد خفيف',
  'thunderstorm with heavy hail': 'عاصفة رعدية مع برد غزير',
};

const WIND_AR = {
  'calm': 'هواء هادئ',
  'light breeze': 'نسيم خفيف',
  'moderate breeze': 'رياح معتدلة',
  'fresh breeze': 'رياح معتدلة',
  'strong wind': 'رياح شديدة ⚠️',
  'near gale': 'رياح شديدة ⚠️',
  'gale': 'رياح شديدة ⚠️',
  'storm': 'رياح شديدة ⚠️',
};

function weatherConditionAr(source) {
  const rawCode = pick(source || {}, 'code', 'weather_code');
  const code = rawCode === '' ? NaN : Number(rawCode);
  if (Number.isFinite(code) && WMO_AR[code]) return WMO_AR[code];
  const raw = clip(pick(source || {}, 'desc', 'description', 'condition'), 60);
  if (!raw) return '';
  if (/[\u0600-\u06FF]/.test(raw)) return raw;
  return DESC_AR[raw.toLowerCase()] || 'طقس متغير';
}

function windCategoryAr(value) {
  if (value === undefined || value === null || String(value).trim() === '') return '';
  const n = Math.round(Number(value));
  if (!Number.isFinite(n)) return '';
  if (n <= 15) return 'هواء هادئ';
  if (n <= 30) return 'نسيم خفيف';
  if (n <= 50) return 'رياح معتدلة';
  return 'رياح شديدة ⚠️';
}

function windLabel(source) {
  const numeric = pick(source || {}, 'wind', 'wind_speed', 'wind_speed_10m', 'wind_speed_max', 'wind_speed_10m_max');
  const fromNumber = windCategoryAr(numeric);
  if (fromNumber) return fromNumber;
  const explicitAr = clip(pick(source || {}, 'wind_ar', 'wind_description_ar', 'wind_category_ar'), 40);
  if (explicitAr) return explicitAr;
  const explicit = clip(pick(source || {}, 'wind_description', 'wind_category'), 40).toLowerCase();
  return WIND_AR[explicit] || '';
}

function placeAr(value) {
  const raw = clip(value, 60);
  if (!raw) return '';
  if (/zagazig/i.test(raw)) return 'الزقازيق، مصر';
  if (/cairo/i.test(raw)) return 'القاهرة، مصر';
  return raw;
}

function durationLabel(minutes) {
  const n = Number(minutes);
  if (!Number.isFinite(n) || n <= 0) return '';
  const hours = Math.floor(n / 60);
  const mins = Math.round(n % 60);
  if (hours && mins) return hours + ' س ' + mins + ' د';
  if (hours) return hours + ' س';
  return mins + ' د';
}

const PRAYER_AR = {
  Fajr: 'الفجر',
  Dhuhr: 'الظهر',
  Asr: 'العصر',
  Maghrib: 'المغرب',
  Isha: 'العشاء',
};

function prayerNameAr(name) {
  const raw = txt(name).trim();
  if (!raw) return '';
  if (/[\u0600-\u06FF]/.test(raw)) return raw;
  return PRAYER_AR[raw] || raw;
}

function prayerNoteAr(note) {
  const raw = txt(note).trim();
  if (!raw) return '';
  if (/[\u0600-\u06FF]/.test(raw)) return raw;
  const key = raw.toLowerCase();
  if (key.includes('next prayer is fajr tomorrow')) return 'الصلاة القادمة: الفجر غداً.';
  if (key.includes('no more prayers today')) return 'لا توجد صلوات متبقية اليوم.';
  return '';
}

function eventStart(event) {
  const start = (event && event.start) || {};
  return start.dateTime || start.date || '';
}

function eventEnd(event) {
  const end = (event && event.end) || {};
  return end.dateTime || end.date || '';
}

function eventIsAllDay(event) {
  return !!(event && event.start && event.start.date && !event.start.dateTime);
}

function eventIsCancelled(event) {
  if (!event) return true;
  if (event.status === 'cancelled') return true;
  const attendees = Array.isArray(event.attendees) ? event.attendees : [];
  return attendees.some((person) => person && person.self && person.responseStatus === 'declined');
}

function eventIsSleep(event) {
  const title = txt(pick(event || {}, 'summary', 'title')).trim();
  return /^sleep$/i.test(title) || /نوم/.test(title);
}

function eventSummary(event) {
  return clip(pick(event || {}, 'summary', 'title') || 'حدث بدون عنوان', 90);
}

function eventTime(event) {
  return eventIsAllDay(event) ? 'طوال اليوم' : timeLabel(eventStart(event));
}

function eventLocation(event) {
  return clip(pick(event || {}, 'location'), 70);
}

function taskIsDone(task) {
  return !!(task && (task.status === 'completed' || task.completed || task.completedAt));
}

function taskTitle(task) {
  return clip(pick(task || {}, 'title', 'content', 'name') || 'مهمة بدون عنوان', 100);
}

function taskDueKey(task) {
  return dayKey(pick(task || {}, 'due', 'dueDate', 'deadline'));
}

function emailLabels(message) {
  const raw = Array.isArray(message && message.labelIds)
    ? message.labelIds
    : (Array.isArray(message && message.labels) ? message.labels : []);
  return raw.map((label) => (typeof label === 'string' ? label : txt(label && (label.name || label.id)))).filter(Boolean);
}

function emailFrom(message) {
  const raw = txt(pick(message || {}, 'From', 'from') || headerValue(message, 'From')).replace(/<[^>]*>/g, '').replace(/"/g, '').trim();
  return clip(raw || 'مرسل غير معروف', 60);
}

function emailSubject(message) {
  return clip(pick(message || {}, 'Subject', 'subject') || headerValue(message, 'Subject') || '(بدون موضوع)', 100);
}

function emailDate(message) {
  return txt(pick(message || {}, 'date', 'Date', 'internalDate') || headerValue(message, 'Date'));
}

function buildBrief(data) {
  const now = data && data.now ? new Date(data.now) : new Date();
  const today = dayKey(now.toISOString());
  const events = Array.isArray(data && data.events) ? data.events : [];
  const tasks = Array.isArray(data && data.tasks) ? data.tasks : [];
  const emails = Array.isArray(data && data.emails) ? data.emails : [];
  const weather = (data && data.weather) || {};
  const prayer = (data && data.prayer) || {};
  const localTodos = Array.isArray(data && data.local_todos) ? data.local_todos : [];
  const reminders = Array.isArray(data && data.reminders) ? data.reminders : [];
  const sourceErrors = [];
  if (events.some((event) => event && event.error)) sourceErrors.push('Calendar');
  if (tasks.some((task) => task && task.error)) sourceErrors.push('Tasks');
  if (emails.some((message) => message && message.error)) sourceErrors.push('Gmail');
  const calendarDown = sourceErrors.includes('Calendar');
  const tasksDown = sourceErrors.includes('Tasks');

  const eventsToday = events
    .filter((event) => event && !event.error && !eventIsCancelled(event) && !eventIsSleep(event) && dayKey(eventStart(event)) === today)
    .map((event) => ({
      summary: eventSummary(event),
      start: eventStart(event),
      end: eventEnd(event),
      allDay: eventIsAllDay(event),
      time: eventTime(event),
      location: eventLocation(event),
      startMs: new Date(eventStart(event)).getTime(),
      endMs: new Date(eventEnd(event)).getTime(),
    }))
    .sort((a, b) => {
      if (a.allDay !== b.allDay) return a.allDay ? -1 : 1;
      return a.startMs - b.startMs;
    });

  const timedEvents = eventsToday.filter((event) => !event.allDay && Number.isFinite(event.startMs));
  const upcomingEvents = timedEvents.filter((event) => !Number.isFinite(event.endMs) || event.endMs > now.getTime());

  const openTasks = tasks
    .filter((task) => task && !task.error && !taskIsDone(task) && pick(task, 'title', 'content', 'name'))
    .map((task) => ({ title: taskTitle(task), dueKey: taskDueKey(task), notes: clip(pick(task || {}, 'notes', 'description'), 180) }));

  const overdueTasks = openTasks
    .filter((task) => task.dueKey && task.dueKey < today)
    .sort((a, b) => a.dueKey.localeCompare(b.dueKey) || a.title.localeCompare(b.title));
  const dueTodayTasks = openTasks
    .filter((task) => task.dueKey === today)
    .sort((a, b) => a.title.localeCompare(b.title));

  const importantEmails = emails
    .filter((message) => message && !message.error)
    .map((message) => {
      const labels = emailLabels(message);
      const subject = emailSubject(message);
      const from = emailFrom(message);
      const snippet = clip(pick(message || {}, 'snippet', 'textPlain', 'text'), 160);
      const action = /(urgent|asap|action required|deadline|due|invoice|payment|interview|contract|security|verify|verification|confirm|booking|appointment|renewal|expires?)/i.test(subject + ' ' + snippet);
      const unread = labels.includes('UNREAD');
      const starred = labels.includes('STARRED');
      const markedImportant = labels.includes('IMPORTANT');
      const promotional = labels.some((label) => /CATEGORY_(PROMOTIONS|SOCIAL|FORUMS)/.test(label));
      const bulk = /(no-?reply|newsletter|promo|marketing|digest|notifications?@|updates?@|support@|noreply)/i.test(from);
      let score = 0;
      if (unread) score += 2;
      if (starred) score += 3;
      if (markedImportant) score += 2;
      if (action) score += 3;
      if (labels.includes('INBOX')) score += 1;
      if (promotional || (bulk && !action)) score -= 6;
      return { from, subject, date: emailDate(message), score, unread, starred, markedImportant, action };
    })
    .filter((message) => message.unread && message.score >= 3 && (message.action || message.starred || message.markedImportant))
    .sort((a, b) => b.score - a.score || (new Date(b.date).getTime() || 0) - (new Date(a.date).getTime() || 0))
    .slice(0, 3);

  const conflicts = [];
  for (let i = 0; i < timedEvents.length && conflicts.length < 2; i += 1) {
    for (let j = i + 1; j < timedEvents.length && conflicts.length < 2; j += 1) {
      const a = timedEvents[i];
      const b = timedEvents[j];
      if (Number.isFinite(a.endMs) && Number.isFinite(b.startMs) && a.startMs < b.endMs && b.startMs < a.endMs) {
        conflicts.push(a.summary + ' (' + a.time + ') يتعارض مع ' + b.summary + ' (' + b.time + ')');
      }
    }
  }

  const priorities = [];
  const addPriority = (text) => {
    const value = clip(text, 120);
    if (value && !priorities.includes(value)) priorities.push(value);
  };
  overdueTasks.slice(0, 2).forEach((task) => {
    const due = shortDate(task.dueKey);
    addPriority('أنجز المتأخر: ' + task.title + (due ? ' (استحق ' + due + ')' : ''));
  });
  dueTodayTasks.slice(0, 2).forEach((task) => addPriority('أكمل اليوم: ' + task.title));
  upcomingEvents.slice(0, 3).forEach((event) => addPriority('استعد لـ ' + event.summary + ' الساعة ' + event.time));
  importantEmails.slice(0, 1).forEach((message) => addPriority('راجع: ' + message.subject));
  localTodos.slice(0, 2).forEach((task) => {
    addPriority('محلي: ' + (pick(task || {}, 'title', 'content', 'text') || 'مهمة'));
  });
  if (!priorities.length) {
    addPriority(calendarDown || tasksDown
      ? 'راجع اتصال Google عشان الأولويات تظهر صح.'
      : 'لا مواعيد نهائية اليوم. اختر مهمة واحدة مهمة.');
  }

  const lines = [];
  lines.push('☀️ موجز الصباح — ' + dateLabel(now));
  lines.push('');
  if (sourceErrors.length) {
    lines.push('⚠️ Google مش متصل (' + sourceErrors.join('، ') + ') — المواعيد والمهام والإيميلات ناقصة.');
    lines.push('');
  }
  lines.push('🎯 الأولويات');
  priorities.slice(0, 3).forEach((priority, index) => lines.push((index + 1) + '. ' + priority));

  lines.push('');
  lines.push('📅 اليوم');
  if (!eventsToday.length) {
    lines.push(calendarDown ? 'مش قادر أقرأ تقويم Google — مش متصل.' : 'لا توجد مواعيد اليوم.');
  } else {
    eventsToday.slice(0, 8).forEach((event) => {
      const location = event.location ? ' — ' + event.location : '';
      lines.push('• ' + event.time + ' — ' + event.summary + location);
    });
  }

  lines.push('');
  lines.push('✅ المهام');
  if (!overdueTasks.length && !dueTodayTasks.length) {
    lines.push(tasksDown ? 'مش قادر أقرأ مهام Google — مش متصل.' : 'لا توجد مهام مستحقة اليوم.');
  } else {
    if (overdueTasks.length) {
      lines.push('متأخرة');
      overdueTasks.slice(0, 4).forEach((task) => {
        const due = shortDate(task.dueKey);
        lines.push('• ' + task.title + (due ? ' — استحق ' + due : ''));
      });
    }
    if (dueTodayTasks.length) {
      lines.push('مستحقة اليوم');
      dueTodayTasks.slice(0, 4).forEach((task) => lines.push('• ' + task.title));
    }
  }

  if (localTodos.length) {
    lines.push('');
    lines.push('📝 مهام محلية');
    localTodos.slice(0, 6).forEach((task) => {
      lines.push('• ' + clip(pick(task || {}, 'title', 'content', 'text') || 'مهمة', 100));
    });
  }

  if (reminders.length) {
    lines.push('');
    lines.push('⏰ تذكيرات');
    reminders.slice(0, 5).forEach((reminder) => {
      const when = timeLabel(pick(reminder || {}, 'remind_at', 'due_at', 'when'));
      const text = clip(pick(reminder || {}, 'text', 'title', 'message') || '', 90);
      lines.push('• ' + (when ? when + ' — ' : '') + text);
    });
  }

  lines.push('');
  const weatherPlace = placeAr(pick(weather, 'location') || 'الزقازيق، مصر');
  lines.push('🌤 الطقس — ' + weatherPlace);
  if (weather.ok === false || weather.error) {
    lines.push('الطقس غير متاح حالياً.');
  } else {
    const current = weather.current || {};
    const currentParts = [];
    if (temp(current.temp)) currentParts.push(temp(current.temp));
    const currentCondition = weatherConditionAr(current);
    if (currentCondition) currentParts.push(currentCondition);
    const currentLine = currentParts.join('، ');
    const extras = [];
    if (temp(current.feels_like)) extras.push('الإحساس ' + temp(current.feels_like));
    const currentWind = windLabel(current);
    if (currentWind) extras.push('الرياح: ' + currentWind);
    if (currentLine) lines.push('الآن: ' + currentLine + (extras.length ? '. ' + extras.join('. ') + '.' : '.'));

    const forecast = Array.isArray(weather.forecast) ? weather.forecast : [];
    const todayForecast = forecast.find((day) => dayKey(day && day.date) === today);
    if (todayForecast) {
      const parts = [];
      const low = temp(todayForecast.min);
      const high = temp(todayForecast.max);
      if (low || high) parts.push((low || '?') + '–' + (high || '?'));
      const condition = weatherConditionAr(todayForecast);
      if (condition) parts.push(condition);
      if (parts.length) {
        let forecastLine = 'اليوم: ' + parts.join('، ');
        const rain = Number(todayForecast.rain_chance);
        if (Number.isFinite(rain) && rain > 30) forecastLine += '. احتمال المطر: ' + Math.round(rain) + '%';
        const dayWind = windLabel(todayForecast);
        if (dayWind) forecastLine += '. الرياح: ' + dayWind;
        lines.push(forecastLine + '.');
      }
    }
    if (!currentLine && !todayForecast) lines.push('الطقس غير متاح حالياً.');
  }

  lines.push('');
  const prayerPlace = placeAr(pick(prayer, 'location') || 'الزقازيق، مصر');
  lines.push('🕌 مواقيت الصلاة — ' + prayerPlace);
  if (prayer.ok === false || prayer.error) {
    lines.push('مواقيت الصلاة غير متاحة حالياً.');
  } else {
    const order = ['Fajr', 'Dhuhr', 'Asr', 'Maghrib', 'Isha'];
    const times = prayer.times || {};
    const parts = order
      .map((name) => {
        const value = times[name];
        return value ? prayerNameAr(name) + ' ' + timeLabel(value) : '';
      })
      .filter(Boolean);
    if (parts.length) lines.push(parts.join(' · '));
    const next = prayer.next_prayer || {};
    if (next.name && next.day !== 'tomorrow') {
      const when = next.at ? timeLabel(next.at) : timeLabel(next.at_12h);
      const wait = durationLabel(next.in_minutes);
      lines.push('القادمة: ' + prayerNameAr(next.name) + (when ? ' الساعة ' + when : '') + (wait ? ' (بعد ' + wait + ')' : '') + '.');
    } else if (!next.name && next.note) {
      const note = prayerNoteAr(next.note);
      if (note) lines.push(note);
    }
  }

  const attention = [];
  importantEmails.forEach((message) => attention.push(message.from + ' — ' + message.subject + ' (غير مقروء)'));
  conflicts.forEach((conflict) => attention.push('تعارض في المواعيد: ' + conflict));
  if (attention.length) {
    lines.push('');
    lines.push('📬 يحتاج انتباه');
    attention.slice(0, 4).forEach((item) => lines.push('• ' + clip(item, 180)));
  }

  let message = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  if (message.length > 3900) message = message.slice(0, 3890).trimEnd() + '…';

  return {
    message,
    stats: {
      events_today: eventsToday.length,
      overdue_tasks: overdueTasks.length,
      tasks_due_today: dueTodayTasks.length,
      important_emails: importantEmails.length,
      conflicts: conflicts.length,
      weather_days: Array.isArray(weather.forecast) ? weather.forecast.length : 0,
      prayer_times: prayer.times ? Object.keys(prayer.times).length : 0,
      priorities: Math.min(priorities.length, 3),
    },
  };
}

